"use client"

import { Switch as SwitchPrimitive } from "@base-ui/react/switch"

import { cn } from "@/lib/utils"
import { useSound } from "./sound-provider"

function Switch({
  className,
  onCheckedChange,
  ...props
}: SwitchPrimitive.Root.Props) {
  const { playClick } = useSound()
  return (
    <SwitchPrimitive.Root
      className={cn(
        "group/switch peer inline-flex h-[1.5rem] w-[2.75rem] shrink-0 cursor-pointer items-center rounded-full border-2 border-transparent transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background data-disabled:cursor-not-allowed data-disabled:opacity-50 data-checked:bg-primary data-unchecked:bg-input",
        className
      )}
      onCheckedChange={(checked, eventDetails) => {
        playClick()
        onCheckedChange?.(checked, eventDetails)
      }}
      {...props}
    >
      <SwitchPrimitive.Thumb
        render={
          <span
            className="pointer-events-none block h-5 w-5 rounded-full bg-background shadow-[0_0.0625rem_0.1875rem_oklch(0_0_0/0.1)] ring-0 data-checked:translate-x-5 data-unchecked:translate-x-0 origin-left data-checked:origin-right rtl:origin-right rtl:data-checked:origin-left transition-[translate,scale,transform-origin,background-color,box-shadow] duration-[260ms,140ms,0ms,150ms,150ms] delay-[0ms,0ms,140ms,0ms,0ms] ease-out motion-safe:group-active/switch:scale-x-[1.18] motion-reduce:transition-none"
          />
        }
      />
    </SwitchPrimitive.Root>
  )
}

export { Switch }
